  int pl=root.getPaddingLeft(),pt=root.getPaddingTop(),pr=root.getPaddingRight(),pb=root.getPaddingBottom();Drawable background=root.getBackground();CharSequence description=root.getContentDescription();boolean clips=root.getClipChildren(),outline=root.getClipToOutline();
